INSERT INTO `logs` VALUES (57, 'error', '服务器未知错误: Unknown column \'passwordStrength\' in \'field list\'', '{\"service\":\"keyVault-log-service\",\"name\":\"SequelizeDatabaseError\",\"parent\":{\"code\":\"ER_BAD_FIELD_ERROR\",\"errno\":1054,\"sqlState\":\"42S22\",\"sqlMessage\":\"Unknown column \'passwordStrength\' in \'field list\'\",\"sql\":\"SELECT AVG(`passwordStrength`) AS `averageStrength` FROM `Passwords` AS `Password` WHERE (`Password`.`deletedAt` IS NULL AND `Password`.`user_id` = \'7f9e2932-a0d5-4df8-aaaa-166ad9b66600\');\"},\"original\":{\"code\":\"ER_BAD_FIELD_ERROR\",\"errno\":1054,\"sqlState\":\"42S22\",\"sqlMessage\":\"Unknown column \'passwordStrength\' in \'field list\'\",\"sql\":\"SELECT AVG(`passwordStrength`) AS `averageStrength` FROM `Passwords` AS `Password` WHERE (`Password`.`deletedAt` IS NULL AND `Password`.`user_id` = \'7f9e2932-a0d5-4df8-aaaa-166ad9b66600\');\"},\"sql\":\"SELECT AVG(`passwordStrength`) AS `averageStrength` FROM `Passwords` AS `Password` WHERE (`Password`.`deletedAt` IS NULL AND `Password`.`user_id` = \'7f9e2932-a0d5-4df8-aaaa-166ad9b66600\');\",\"parameters\":{},\"stack\":\"Error\\n    at Query.run (F:\\\\electron\\\\backend-service\\\\node_modules\\\\.pnpm\\\\sequelize@6.37.7_mysql2@3.15.3\\\\node_modules\\\\sequelize\\\\lib\\\\dialects\\\\mysql\\\\query.js:52:25)\\n    at F:\\\\electron\\\\backend-service\\\\node_modules\\\\.pnpm\\\\sequelize@6.37.7_mysql2@3.15.3\\\\node_modules\\\\sequelize\\\\lib\\\\sequelize.js:315:28\\n    at process.processTicksAndRejections (node:internal/process/task_queues:105:5)\\n    at async MySQLQueryInterface.select (F:\\\\electron\\\\backend-service\\\\node_modules\\\\.pnpm\\\\sequelize@6.37.7_mysql2@3.15.3\\\\node_modules\\\\sequelize\\\\lib\\\\dialects\\\\abstract\\\\query-interface.js:407:12)\\n    at async Password.findAll (F:\\\\electron\\\\backend-service\\\\node_modules\\\\.pnpm\\\\sequelize@6.37.7_mysql2@3.15.3\\\\node_modules\\\\sequelize\\\\lib\\\\model.js:1140:21)\\n    at async getPasswordStrengthAverage (F:\\\\electron\\\\backend-service\\\\controllers\\\\passwordController.js:827:22)\"}', '2025-12-08 22:02:15');
