INSERT INTO `Passwords` VALUES ('010c143a-595f-475a-a667-8018a387a650', '7f9e2932-a0d5-4df8-aaaa-166ad9b66600', '9b3931ca-1aa7-4cdc-8655-245ba9d60713', 'YouTube', 'test0001', 'eyJzYWx0IjoiOTdmMDZiNjI0ZWU2YjhiZDhmMmYzZTI0ZDE5YzlkYjMiLCJpdiI6IjYyNGE1MGFmZTM2ZGE1YWU1NGY3MTg0NWY3MGUyYzRlIiwiYXV0aFRhZyI6ImZkZjQ3ZGQxNjNkZTJmZDA1MGY3NzM5ODRlN2NhNjI4IiwiZW5jcnlwdGVkRGF0YSI6IjJlNDRkMjI5NTkyMDkyYzMyMjlkNTJhNDE2In0=', 'https://www.youtube.com/', 'YouTube 是 2005 年由前 PayPal 员工陈士骏等人创立的全球顶尖视频分享与社交媒体平台，2006 年被 Google 收购。平台以 “表现你自己” 为理念，汇聚超 27 亿月活用户，内容覆盖娱乐、教育、新闻、游戏等多元领域。它支持视频上传、直播、互动评论等功能，构建了完善的创作者变现生态，既是用户获取信息、休闲娱乐的核心渠道，也是全球文化传播与交流的重要桥梁。', 0, NULL, '{}', 4, '2025-12-09 19:16:30', '2025-12-08 23:55:49', '2025-12-10 23:05:39');
