INSERT INTO `Passwords` VALUES ('8a1bf31c-b9e6-45fd-932d-d41ebe5d955b', '7f9e2932-a0d5-4df8-aaaa-166ad9b66600', '892af673-bfe2-4347-9fd4-f008c3d0cc05', 'Instagram', 'wenqiangsun990@gmail.com', 'eyJzYWx0IjoiYTMyMWM4MTFkMzgwMzhiZGUyZTI2OGUzYTk2YWM0MGMiLCJpdiI6IjZmYTg5YzE5ZTkxZWNjZWYxN2NhYzdmMTlhNzE3MjQ4IiwiYXV0aFRhZyI6ImViOWJmNjE0YmFiNzFjNDBmOTZlYjliYzdjN2Q1ZjQwIiwiZW5jcnlwdGVkRGF0YSI6ImI3ZjZiNTAwNTljYmJmZGIifQ==', 'https://www.instagram.com/', 'Instagram（简称 Ins）是 2010 年由凯文・斯特罗姆等人创立的视觉社交平台，2012 年被 Meta（原 Facebook）收购。平台以图片、短视频为核心，支持滤镜美化、Stories 快拍、Reels 短视频等功能，月活用户超 30 亿。它聚焦年轻群体，兼具生活分享、灵感探索与品牌营销属性，构建了完善的创作者变现与电商生态，成为全球流行的视觉表达与社交互动阵地。', 0, NULL, '{}', 2, '2025-12-09 19:22:03', '2025-12-08 19:28:30', '2025-12-09 19:22:03');
INSERT INTO `Passwords` VALUES ('b44a02ab-c0a6-4d11-a5e5-a4cdbd984145', '7f9e2932-a0d5-4df8-aaaa-166ad9b66600', 'f07ec329-1458-4c71-bb1d-361d6a060577', 'stackoverflow', 'test002', 'eyJzYWx0IjoiNzY4YWFkYTMwYTU0NzIxY2UzMzZlNjBhZjdkODIyMzMiLCJpdiI6IjEzMmIzZTQ2MTc5N2U1YzBkMjFmY2U0ODIzM2YzODkzIiwiYXV0aFRhZyI6IjkyMDlkNTE2MmVjY2ExYjQzMTVmOWNmZTdjYTI1NjcwIiwiZW5jcnlwdGVkRGF0YSI6IjU3NjM3OTE3YjVmNjcyODQyYWRlMWZhODg3OWMifQ==', 'https://stackoverflow.com/questions', 'Stack Overflow 是 2008 年由 Jeff Atwood 和 Joel Spolsky 创立的全球顶尖编程问答社区，隶属于 Stack Exchange 网络。平台以社区驱动为核心，通过投票、声誉积分机制保障内容质量，支持标签分类与代码片段分享，沉淀了海量高质量技术问答。它是开发者解决编程难题、交流经验的核心阵地，凭借开放免费的特性和高效的知识检索体验，成为全球程序员不可或缺的工具。', 0, NULL, '{}', 4, '2025-12-10 17:28:08', '2025-12-09 00:02:11', '2025-12-10 23:08:04');
INSERT INTO `Passwords` VALUES ('f2a886e0-d113-4066-8d9d-ab7243040822', '7f9e2932-a0d5-4df8-aaaa-166ad9b66600', '264c7f7d-bd33-4da3-ba4e-35a74ac8b4bc', 'Steam', 'test001', 'eyJzYWx0IjoiMDIyNWQ2MTRjYzhmYmFiYzJhYWYyNjQ2ODA1Mzc1YWIiLCJpdiI6IjJmZDUwMDI0ZTkwMzIwZGRjZTMxNTgyZjNiYzgyNWZmIiwiYXV0aFRhZyI6Ijc2YWU5OWIxMjUxMmNkNGM1ZjRjNjQ1ZjExMTZjY2JlIiwiZW5jcnlwdGVkRGF0YSI6IjQ2NGM2NzZlODRkNWU2NDc4MTJlYzQ5ZGZkIn0=', 'https://store.steampowered.com/', 'Steam 是 Valve 打造的全球顶级数字游戏平台，汇聚超 3 万款游戏，涵盖 3A 大作与独立佳作。核心功能包括游戏购买、跨平台联机、创意工坊（模组分享）及云存档，支持 Windows、macOS 等多系统。中文用户占比领先，季节性促销折扣丰厚，兼具社交互动与内容共创生态，是全球玩家与开发者的核心聚集地。', 1, NULL, '{}', 4, '2025-12-10 23:11:48', '2025-12-09 23:15:49', '2025-12-10 23:12:43');
